import{_ as r,o as l,c as i,a3 as n,j as t,a,t as s}from"./chunks/framework.BTQ4eCVb.js";const f=JSON.parse('{"title":"Email","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Email | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/email"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Email | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/email"}]]},"headers":[],"relativePath":"user-guide/email.md","filePath":"user-guide/email.md","lastUpdated":1787680328000}'),d={name:"user-guide/email.md"};function m(o,e,g,p,c,u){return l(),i("div",null,[e[14]||(e[14]=n('<h1 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h1><p>Connect <strong>one or more personal</strong> mailboxes to EloSync with IMAP (receive) and SMTP (send). Browse Inbox and folders, compose drafts, send mail, and manage reusable templates and signatures.</p><p>Email is a free Marketplace opt-in module. Mailboxes and signatures stay <strong>personal</strong> — each user connects and sees only their own accounts, folders, and messages. Templates can be <strong>shared</strong> with the workspace or kept private.</p><h2 id="not-the-same-as-platform-mail-or-communication-templates" tabindex="-1">Not the same as platform mail or Communication Templates <a class="header-anchor" href="#not-the-same-as-platform-mail-or-communication-templates" aria-label="Permalink to &quot;Not the same as platform mail or Communication Templates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Email</strong> (this module)</td><td>Your personal IMAP/SMTP inbox inside EloSync</td></tr><tr><td><strong>Settings → Mail</strong></td><td>Workspace / system <strong>transactional</strong> delivery (invites, password resets, digests, notifications). See <a href="/user-guide/tenant-settings#mail">Tenant Settings</a>.</td></tr><tr><td><strong>Communication Templates</strong></td><td>Shared plain-text templates for channels such as WhatsApp from Leads. See <a href="/user-guide/communication-templates">Communication Templates</a>.</td></tr><tr><td><strong>Email Logs</strong></td><td>Delivery history for platform/workspace outgoing mail — not your personal mailbox</td></tr></tbody></table><p>Personal mailbox SMTP credentials are <strong>not</strong> the Settings → Mail provider. Connecting Gmail/Outlook here does not change how EloSync sends system notifications.</p><h2 id="install-from-marketplace" tabindex="-1">Install from Marketplace <a class="header-anchor" href="#install-from-marketplace" aria-label="Permalink to &quot;Install from Marketplace&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong>.</li><li>Find <strong>Email</strong> (Communication category).</li><li>Click <strong>Install</strong> (free — <code>$0</code>; not included by default on new workspaces).</li></ol><p>You need Marketplace purchase permission to install. After install, your role still needs Email permissions (below) and you must connect a mailbox.</p><h2 id="connect-imap-smtp" tabindex="-1">Connect IMAP / SMTP <a class="header-anchor" href="#connect-imap-smtp" aria-label="Permalink to &quot;Connect IMAP / SMTP&quot;">​</a></h2><ol><li>Open <strong>Email</strong> in the navigation.</li><li>If you have no account, use <strong>Connect your mailbox</strong>. To add another, use <strong>Add mailbox</strong>.</li><li>Choose a preset or <strong>Custom</strong>: <ul><li><strong>Gmail</strong> — IMAP/SMTP hosts and ports prefilled; use a Google <a href="https://support.google.com/accounts/answer/185833" target="_blank" rel="noreferrer">App Password</a> (2-Step Verification required). OAuth sign-in is not available in this version.</li><li><strong>Outlook / Microsoft 365</strong> — hosts prefilled; use an app password or SMTP authenticated credentials as your provider allows. OAuth is not available in this version.</li><li><strong>Custom</strong> — enter IMAP and SMTP host, port, encryption, and username/password yourself.</li></ul></li><li>Enter email address, display name, passwords, and <strong>Auto-sync interval</strong> (default <strong>every 5 minutes</strong>; options 5 / 10 / 15 / 30 / 60).</li><li>Optionally mark <strong>Default mailbox</strong> (used as the starting From when you compose).</li><li><strong>Test</strong> the connection, then save.</li></ol><p>Use the mailbox switcher on the Email page to change which inbox you are viewing. Under <strong>Actions</strong> you can edit credentials, <strong>Set as default</strong>, or <strong>Disconnect</strong>.</p><p>Your mail provider must allow SMTP from the application server’s IP. If <strong>Test connection</strong> times out after IMAP works, ask the provider to permit SMTP (ports <strong>587</strong> and/or <strong>465</strong>) for that server IP.</p><p><strong>Manual Sync</strong> on the Email page still runs anytime. Background sync uses each mailbox’s interval when the scheduler and <code>email-sync</code> queue worker are running.</p><p>Disconnect removes the account and synced folders, labels, and messages from EloSync for that mailbox (mail remains on the provider). Attachment <strong>download and upload are not available in this version</strong>; a paperclip badge may appear when the provider reports attachments on a message.</p><h2 id="inbox-and-folders" tabindex="-1">Inbox and folders <a class="header-anchor" href="#inbox-and-folders" aria-label="Permalink to &quot;Inbox and folders&quot;">​</a></h2><p>After connect and sync:</p><ul><li>Folders appear in a left pane (Inbox, Drafts, Sent, Trash, Spam, and custom folders from the server).</li><li>Select a folder to list messages; open a row to read in the reading pane. HTML messages render as full HTML (styled layout) in a sandboxed viewer after sanitization; plain-text-only messages show as text.</li><li>Use the <strong>reading pane</strong> control (layout icon next to search) to switch between <strong>Right panel</strong> (default, resizable list width) and <strong>Full panel</strong> (message fills the content area; <strong>Back to list</strong> returns to the split view without changing your saved layout preference). Your choice is remembered in the browser.</li><li>Search filters the current folder (or label) list.</li><li>Use checkboxes to <strong>select multiple messages</strong> (or select all visible in the current list), then <strong>Mark read / unread</strong>, <strong>Move to</strong>, <strong>Labels</strong>, or <strong>Delete</strong> from the bulk toolbar (up to 25 messages per bulk request). Delete follows the same Trash vs permanent rules as a single message.</li><li><strong>Reply</strong> / <strong>Forward</strong> from the reading pane opens Compose with the thread quoted.</li><li><strong>Move to</strong> lets you pick another synced folder (IMAP move).</li><li><strong>Delete</strong> moves the message to <strong>Trash</strong> when that folder exists; deleting again from Trash permanently removes it. If the message is already gone from your real mailbox (deleted in Gmail/Outlook), EloSync still removes it from the Email module instead of showing an error. Temporary mailbox connection failures keep the EloSync copy and show an error so mail is not lost.</li></ul><p>Unread counts refresh with sync. Creating folders happens in your mail provider or webmail, then <strong>Sync</strong> in EloSync — folder create from the EloSync UI is not available in this version.</p><h2 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h2><p>Labels are <strong>EloSync-only</strong> tags for organizing mail. They do <strong>not</strong> sync to Gmail/Outlook IMAP folders.</p><ul><li>Under folders in the left pane, the <strong>Labels</strong> heading lists your labels for the selected mailbox.</li><li>Use the tags icon next to <strong>Labels</strong> to create, rename, recolor, or delete labels.</li><li>Open a message and use <strong>Labels</strong> in the reading pane to apply or remove labels (a message can have several).</li><li>Or select several messages and use the bulk <strong>Labels</strong> menu to add or remove a label across the selection.</li><li>Click a label in the sidebar to list every message on that mailbox that has the label (across folders).</li></ul><p>Disconnecting a mailbox removes its EloSync labels and assignments. Mail on your provider is unchanged.</p><h2 id="compose-drafts-and-sent" tabindex="-1">Compose, drafts, and sent <a class="header-anchor" href="#compose-drafts-and-sent" aria-label="Permalink to &quot;Compose, drafts, and sent&quot;">​</a></h2>',24)),t("ol",null,[e[6]||(e[6]=t("li",null,[a("Click "),t("strong",null,"Compose"),a(" (or "),t("strong",null,"Reply"),a(" / "),t("strong",null,"Forward"),a(" on a message).")],-1)),e[7]||(e[7]=t("li",null,[a("Choose "),t("strong",null,"From"),a(" among your connected mailboxes (defaults to your default mailbox, or the inbox you are viewing).")],-1)),e[8]||(e[8]=t("li",null,"Fill To / Cc / Bcc, subject, and body in the rich text editor (bold, italic, underline, lists, links, text color).",-1)),t("li",null,[e[0]||(e[0]=a("Optionally apply a ",-1)),e[1]||(e[1]=t("strong",null,"template",-1)),e[2]||(e[2]=a(" (fill ",-1)),t("code",null,s(o.variables),1),e[3]||(e[3]=a(") and choose a ",-1)),e[4]||(e[4]=t("strong",null,"signature",-1)),e[5]||(e[5]=a(".",-1))]),e[9]||(e[9]=t("li",null,[t("strong",null,"Save draft"),a(" or "),t("strong",null,"Send"),a(".")],-1))]),e[15]||(e[15]=t("p",null,[a("Outbound mail uses the SMTP credentials of the "),t("strong",null,"selected From account"),a(", not Settings → Mail. Replies send "),t("code",null,"In-Reply-To"),a(" / thread metadata when available from the original message. Reply and Forward quote the original message as formatted HTML (not raw source).")],-1)),e[16]||(e[16]=t("h2",{id:"templates",tabindex:"-1"},[a("Templates "),t("a",{class:"header-anchor",href:"#templates","aria-label":'Permalink to "Templates"'},"​")],-1)),t("p",null,[e[10]||(e[10]=a("Email templates store a subject and rich-text body with optional ",-1)),t("code",null,s(o.snake_case),1),e[11]||(e[11]=a(" placeholders you fill when composing. Use the same formatting toolbar as compose. Templates are identified by ",-1)),e[12]||(e[12]=t("strong",null,"id/uuid",-1)),e[13]||(e[13]=a(" (names do not need to be unique across the workspace).",-1))]),e[17]||(e[17]=n('<ol><li>Open <strong>Email → Templates</strong> (or the Templates tab).</li><li>Create / edit name, category, subject, body, and variable list.</li><li>Leave <strong>Shared with workspace</strong> on (default) so teammates can apply the template when composing, or turn it off for a <strong>private</strong> template only you can use.</li><li>Toggle <strong>Active</strong> to hide a template from the compose picker without deleting it.</li></ol><p><strong>Who can edit or delete:</strong> the creator, or the workspace owner (superadmin). Teammates can apply shared templates but cannot change them.</p><p>In compose, the template picker shows <strong>name · creator · Shared/Private</strong> so similarly named templates are easy to tell apart. These templates are separate from <a href="/user-guide/communication-templates">Communication Templates</a> (WhatsApp and shared channel messages).</p><h2 id="signatures" tabindex="-1">Signatures <a class="header-anchor" href="#signatures" aria-label="Permalink to &quot;Signatures&quot;">​</a></h2><ol><li>Open <strong>Email → Signatures</strong>.</li><li>Create signatures in the rich text editor; mark one as <strong>default</strong> for compose.</li></ol><p>Signatures remain <strong>personal</strong> (per user) — they are never shared with the workspace.</p><h2 id="not-yet-in-the-spa" tabindex="-1">Not yet in the SPA <a class="header-anchor" href="#not-yet-in-the-spa" aria-label="Permalink to &quot;Not yet in the SPA&quot;">​</a></h2><p>These capabilities exist partially on the API/schema but are <strong>not exposed in the Email UI</strong> in this version:</p><ul><li><strong>CRM links</strong> (API can attach a message to a Lead/Contact/Company/Opportunity when you can view that record) — no link control in the reading pane yet</li><li><strong>Attachment download / compose attach</strong> — sync may flag <code>has_attachments</code>; files are not fetched into EloSync storage yet</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th><th>Typical roles</th></tr></thead><tbody><tr><td>View inbox / folders / labels / messages</td><td><code>email.view</code></td><td>Admin, Manager</td></tr><tr><td>Compose / draft / send / flags / move / labels</td><td><code>email.create</code> / <code>email.update</code> / <code>email.delete</code></td><td>Admin, Manager</td></tr><tr><td>Connect / update / sync / disconnect accounts</td><td><code>email.accounts.manage</code></td><td>Admin, Manager</td></tr><tr><td>Manage templates</td><td><code>email.templates.manage</code></td><td>Admin, Manager</td></tr><tr><td>Manage personal signatures</td><td><code>email.signatures.manage</code></td><td>Admin, Manager</td></tr></tbody></table><p>Workspace owners (superadmin) have full access when the module is installed. Policies still enforce <strong>personal isolation</strong> for mailboxes and signatures — you cannot open another user’s mailbox. Shared templates are visible/usable to entitled teammates; private templates stay creator-only for use, while the owner may still edit them.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/communication-templates">Communication Templates</a></li><li><a href="/user-guide/tenant-settings#mail">Tenant Settings — Mail</a></li><li><a href="/user-guide/tenant-application#marketplace-add--remove-modules">Marketplace</a></li></ul>',14))])}const b=r(d,[["render",m]]);export{f as __pageData,b as default};
